pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C, Log} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(address(new Log())); }

    function testFuzz_property(uint256 amount, uint256 unlockTime, address actor) public {
        vm.assume(actor != address(c) && actor != address(this));
        amount = bound(amount, 1 ether, 100 ether);
        vm.deal(actor, amount);

        vm.prank(actor);
        c.Put{value: amount}(unlockTime);

        // After the unlock time has passed, the actor must be able to withdraw the deposit.
        vm.warp(block.timestamp + 1);
        vm.prank(actor);
        c.Collect(amount);

        // The full deposit must have been paid out of the contract.
        assertTrue(address(c).balance == 0);
    }
}

