// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C, Log} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(address(new Log())); }

    function testFuzz_property(address actor1, uint256 v1, address actor2, uint256 v2, uint256 t) public {
        vm.assume(actor1 != address(0) && actor2 != address(0) && actor1 != actor2);
        vm.assume(actor1 != address(c) && actor2 != address(c));
        v1 = bound(v1, 1, 100 ether);
        v2 = bound(v2, 0, 100 ether);
        t = bound(t, 0, 2 ** 60);

        // actor1 deposits v1
        vm.deal(actor1, v1);
        vm.prank(actor1);
        c.Put{value: v1}(t);

        // a second, independent actor deposits v2 (must not disturb actor1's record)
        vm.deal(actor2, v2);
        vm.prank(actor2);
        c.Put{value: v2}(t + 1);

        // Deposit isolation: actor1's recorded balance is exactly the amount they deposited,
        // regardless of any subsequent deposits by anyone else.
        assertTrue(c.Acc(actor1).balance == v1);
    }
}

