pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C, Log} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    Log log;

    function setUp() public {
        log = new Log();
        c = new C(address(log));
    }

    function testFuzz_property(uint256 value, address actor) public {
        vm.assume(actor != address(0));
        vm.assume(actor != address(c));
        value = bound(value, 1, 1 ether);

        vm.deal(actor, value);
        vm.prank(actor);
        c.Put{value: value}(0);

        uint256 len = log.HistoryLength();
        (address sender,, uint256 val, uint256 time) = log.History(len - 1);
        assertTrue(len >= 1 && sender == actor && val == value && time == block.timestamp);
    }
}

