    {
        require(_am >= 1 ether);
        require(address(this).balance >= _am);
        c.Put{value: 2 * _am}(0);
        uint before = c.Acc(address(this)).balance;
        c.Collect(_am);
        uint afterB = c.Acc(address(this)).balance;
        assert(afterB == before - _am);
    }

